parameters.jsCode:
const b = $('Webhook: create-issue').first().json.body || {};
const allIssues = $input.all().map(i => i.json).filter(i => i && i.number && !i.pull_request);

const openIssues = allIssues.filter(i => i.state === 'open');
const closedIssues = allIssues.filter(i => i.state === 'closed');

// Check duplicate based on title similarity in OPEN issues
let duplicate = null;
const words = (b.title || '').toLowerCase().split(/\s+/).filter(w => w.length > 3);

if (!b.force_create && words.length > 0) {
  for (const existing of openIssues) {
    const exTitle = (existing.title || '').toLowerCase();
    const matchCount = words.filter(w => exTitle.includes(w)).length;
    if (matchCount >= 2 || (words.length === 1 && exTitle.includes(words[0]))) {
      duplicate = { number: existing.number, title: existing.title };
      break;
    }
  }
}

// Find historical similar resolved (CLOSED) issues
let historicalMatches = [];
if (words.length > 0) {
  for (const past of closedIssues) {
    const pastTitle = (past.title || '').toLowerCase();
    const matchCount = words.filter(w => pastTitle.includes(w)).length;
    if (matchCount >= 2 || (words.length === 1 && pastTitle.includes(words[0]))) {
      historicalMatches.push({
        number: past.number,
        title: past.title,
        url: past.html_url
      });
      if (historicalMatches.length >= 2) break;
    }
  }
}

// Determine severity & component
const validSevs = ['low', 'medium', 'high', 'critical'];
const sev = validSevs.includes(b.severity_hint) ? b.severity_hint : 'medium';

const validComps = ['typescript', 'python', 'docs', 'frontend', 'api', 'database'];
let comp = validComps.includes(b.component_hint) ? b.component_hint : null;

if (!comp) {
  const text = ((b.title || '') + ' ' + (b.description || '')).toLowerCase();
  if (text.includes('py') || text.includes('python') || text.includes('pytest') || text.includes('fastapi')) {
    comp = 'python';
  } else if (text.includes('ts') || text.includes('typescript') || text.includes('node') || text.includes('npm')) {
    comp = 'typescript';
  } else if (text.includes('doc') || text.includes('readme')) {
    comp = 'docs';
  } else {
    comp = 'typescript';
  }
}

let compPath = '';
if (comp === 'python') {
  compPath = 'packages/smooth-api-py';
} else if (comp === 'typescript') {
  compPath = 'packages/smooth-api-ts';
}

const baseBody = [
  '## Description', b.description || 'No description provided',
  '## Steps to reproduce', b.steps_to_reproduce || '_not provided_',
  '## Environment', b.environment || '_not provided_'
].join('\n\n');

return [{
  json: {
    duplicate,
    historical_matches: historicalMatches,
    title: b.title,
    baseBody,
    sev,
    comp,
    compPath,
    labels: ['reported', `sev:${sev}`, `comp:${comp}`]
  }
}];

