parameters.jsCode:
const triage = $('Triage & Check Duplicate').first().json;
const items = $input.all();

let commitLines = [];
let recentCommits = [];

for (const item of items) {
  const c = item.json;
  if (c && c.sha && c.commit) {
    const shortSha = c.sha.substring(0, 7);
    const author = (c.commit.author && c.commit.author.name) || (c.author && c.author.login) || 'unknown';
    const firstLine = (c.commit.message || '').split('\n')[0].trim();
    const url = c.html_url || `https://github.com/aryanSharma48/smoothapi/commit/${c.sha}`;
    commitLines.push(`- [\`${shortSha}\`](${url}) - **${firstLine}** (by @${author})`);
    recentCommits.push({ sha: shortSha, author, message: firstLine });
  }
}

let commitSection = '';
if (commitLines.length > 0) {
  const pathLabel = triage.compPath ? ` in \`${triage.compPath}\`` : '';
  commitSection = `\n\n## 🔍 Recent Changes & Suspect Commits${pathLabel}\n` + commitLines.join('\n');
}

let historySection = '';
if (triage.historical_matches && triage.historical_matches.length > 0) {
  const historyLines = triage.historical_matches.map(h => `- [#${h.number}](${h.url}) - **${h.title}** (Resolved/Closed)`);
  historySection = '\n\n## 📜 Historical Precedents & Related Past Issues\n' + historyLines.join('\n');
}

const finalBody = triage.baseBody + commitSection + historySection + '\n\n---\n_Filed automatically by VoiceBugBot_';

return [{
  json: {
    title: triage.title,
    body: finalBody,
    labels: triage.labels,
    sev: triage.sev,
    comp: triage.comp,
    has_commits: commitLines.length > 0,
    recent_commits: recentCommits,
    historical_matches: triage.historical_matches || []
  }
}];

